    65→export function extractRecordId(url: string | null | undefined): string | null {
    66→  if (!url) return null;
    67→  // Extrahiere die letzten 24 Hex-Zeichen mit Regex
    68→  const match = url.match(/([a-f0-9]{24})$/i);
    69→  return match ? match[1] : null;
    70→}
