    72→export function createRecordUrl(appId: string, recordId: string): string {
    73→  return `https://my.living-apps.de/rest/apps/${appId}/records/${recordId}`;
    74→}
    75→
    76→async function callApi(method: string, endpoint: string, data?: any) {
    77→  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    78→    method,
    79→    headers: { 'Content-Type': 'application/json' },
    80→    credentials: 'include',  // Nutze Session Cookies für Auth
    81→    body: data ? JSON.stringify(data) : undefined
    82→  });
    83→  if (!response.ok) throw new Error(await response.text());
    84→  // DELETE returns often empty body or simple status
    85→  if (method === 'DELETE') return true;
    86→  return response.json();
    87→}
