    89→export class LivingAppsService {
    90→  // --- RECHNUNG ---
    91→  static async getRechnung(): Promise<Rechnung[]> {
    92→    const data = await callApi('GET', `/apps/${APP_IDS.RECHNUNG}/records`);
    93→    return Object.entries(data).map(([id, rec]: [string, any]) => ({
    94→      record_id: id, ...rec
    95→    }));
    96→  }
    97→  static async getRechnungEntry(id: string): Promise<Rechnung | undefined> {
    98→    const data = await callApi('GET', `/apps/${APP_IDS.RECHNUNG}/records/${id}`);
    99→    return { record_id: data.id, ...data };
   100→  }
   101→  static async createRechnungEntry(fields: Rechnung['fields']) {
   102→    return callApi('POST', `/apps/${APP_IDS.RECHNUNG}/records`, { fields });
   103→  }
   104→  static async updateRechnungEntry(id: string, fields: Partial<Rechnung['fields']>) {
