   236→import { useState, useEffect, useMemo, useCallback } from 'react';
   237→import type { Rechnung } from '@/types/app';
   238→import { LivingAppsService } from '@/services/livingAppsService';
   239→
   240→export function useDashboardData() {
   241→  const [rechnung, setRechnung] = useState<Rechnung[]>([]);
   242→  const [loading, setLoading] = useState(true);
   243→  const [error, setError] = useState<Error | null>(null);
   244→
   245→  const fetchAll = useCallback(async () => {
   246→    setError(null);
   247→    try {
   248→      const [rechnungData] = await Promise.all([
   249→        LivingAppsService.getRechnung(),
   250→      ]);
   251→      setRechnung(rechnungData);
   252→    } catch (err) {
   253→      setError(err instanceof Error ? err : new Error('Failed to load data'));
   254→    } finally {
   255→      setLoading(false);
   256→    }
   257→  }, []);
   258→
   259→  useEffect(() => { fetchAll(); }, [fetchAll]);
   260→
   261→  return { rechnung, setRechnung, loading, error, fetchAll };
   262→}
