   308→## src/lib/ai.ts
   309→```
   310→const AI_ENDPOINT = "https://my.living-apps.de/litellm/v1/chat/completions";
   311→const AI_MODEL = "default";
   312→
   313→export type ChatMessage = {
   314→  role: "system" | "user" | "assistant";
   315→  content: string | Array<{ type: string; [key: string]: unknown }>;
   316→};
   317→
   318→type CompletionOptions = {
   319→  temperature?: number;
   320→  max_tokens?: number;
   321→  top_p?: number;
   322→  stop?: string[];
   323→  response_format?: { type: string };
   324→};
   325→
   326→export async function chatCompletion(
   327→  messages: ChatMessage[],
   328→  options: CompletionOptions = {}
   329→): Promise<string> {
   330→  const res = await fetch(AI_ENDPOINT, {
   331→    method: "POST",
   332→    headers: { "Content-Type": "application/json", Accept: "application/json" },
   333→    body: JSON.stringify({ model: AI_MODEL, messages, ...options }),
   334→  });
   335→  if (!res.ok) {
   336→    const body = await res.text();
   337→    throw new Error(`AI API ${res.status}: ${body}`);
   338→  }
   339→  const data = await res.json();
   340→  return data.choices[0].message.content;
   341→}
   342→
   343→export async function safeJsonCompletion<T = unknown>(
   344→  messages: ChatMessage[],
   345→  options: CompletionOptions = {}
   346→): Promise<T> {
   347→  const raw = await chatCompletion(messages, options);
   348→  const match = raw.match(/\{[\s\S]*\}|\[[\s\S]*\]/);
   349→  if (!match) throw new Error(`Expected JSON but got: ${raw.slice(0, 200)}`);
   350→  return JSON.parse(match[0]);
   351→}
   352→
   353→export async function withRetry<T>(fn: () => Promise<T>, maxAttempts = 3): Promise<T> {
   354→  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
   355→    try {
   356→      return await fn();
   357→    } catch (err) {
   358→      if (attempt === maxAttempts) throw err;
   359→      await new Promise((r) => setTimeout(r, 1000 * attempt));
   360→    }
   361→  }
   362→  throw new Error("unreachable");
   363→}
   364→
   365→// --- File encoding helpers ---
   366→
   367→export function fileToDataUri(file: File): Promise<string> {
   368→  return new Promise((resolve, reject) => {
   369→    const reader = new FileReader();
   370→    reader.onload = () => resolve(reader.result as string);
   371→    reader.onerror = () => reject(new Error("Failed to read file"));
   372→    reader.readAsDataURL(file);
   373→  });
   374→}
   375→
   376→export async function urlToDataUri(url: string): Promise<string> {
   377→  const res = await fetch(url);
   378→  const blob = await res.blob();
   379→  return new Promise((resolve, reject) => {
   380→    const reader = new FileReader();
   381→    reader.onload = () => resolve(reader.result as string);
   382→    reader.onerror = () => reject(new Error("Failed to encode file"));
   383→    reader.readAsDataURL(blob);
   384→  });
   385→}
   386→
   387→// --- High-level AI features ---
   388→
   389→export async function classify(
   390→  text: string,
   391→  categories: string[]
   392→): Promise<{ category: string; confidence: number }> {
   393→  return safeJsonCompletion([
   394→    {
   395→      role: "system",
   396→      content: [
   397→        "You are a classifier. Respond ONLY with valid JSON, nothing else.",
   398→        'Output format: {"category": "<one of the allowed categories>", "confidence": <0-1>}',
   399→        `Allowed categories: ${JSON.stringify(categories)}`,
   400→      ].join("\n"),
   401→    },
   402→    { role: "user", content: text },
   403→  ], { temperature: 0 });
   404→}
   405→
   406→export async function extract<T = Record<string, unknown>>(
   407→  text: string,
   408→  schemaDescription: string
   409→): Promise<T> {
   410→  return safeJsonCompletion([
   411→    {
   412→      role: "system",
   413→      content: [
   414→        "You are a data extraction engine. Respond ONLY with valid JSON matching the requested schema.",
   415→        "If a field cannot be determined from the input, use null.",
   416→        `Schema:\n${schemaDescription}`,
   417→      ].join("\n"),
   418→    },
   419→    { role: "user", content: text },
   420→  ], { temperature: 0 });
   421→}
   422→
   423→export async function summarize(
   424→  text: string,
   425→  options: { maxSentences?: number; language?: string } = {}
   426→): Promise<string> {
   427→  const { maxSentences = 3, language } = options;
   428→  const instructions = [
   429→    `Summarize the following text in at most ${maxSentences} sentences.`,
   430→    "Be concise and preserve key facts.",
   431→  ];
   432→  if (language) instructions.push(`Write the summary in ${language}.`);
   433→  return chatCompletion([
   434→    { role: "system", content: instructions.join(" ") },
   435→    { role: "user", content: text },
   436→  ]);
   437→}
   438→
   439→export async function translate(
   440→  text: string,
   441→  targetLanguage: string,
   442→  sourceLanguage?: string
   443→): Promise<string> {
   444→  const from = sourceLanguage ? ` from ${sourceLanguage}` : "";
   445→  return chatCompletion([
   446→    {
   447→      role: "system",
   448→      content: `Translate the following text${from} to ${targetLanguage}. Output ONLY the translation, nothing else.`,
   449→    },
   450→    { role: "user", content: text },
   451→  ]);
   452→}
   453→
   454→export async function analyzeImage(imageDataUri: string, prompt: string): Promise<string> {
   455→  return chatCompletion([
   456→    {
   457→      role: "user",
   458→      content: [
   459→        { type: "text", text: prompt },
   460→        { type: "image_url", image_url: { url: imageDataUri } },
   461→      ],
   462→    },
   463→  ]);
   464→}
   465→
   466→export async function analyzeDocument(fileDataUri: string, prompt: string): Promise<string> {
   467→  return chatCompletion([
   468→    {
   469→      role: "user",
   470→      content: [
   471→        { type: "text", text: prompt },
   472→        { type: "file", file: { file_data: fileDataUri } },
   473→      ],
   474→    },
   475→  ]);
   476→}
   477→
   478→export async function extractFromPhoto<T = Record<string, unknown>>(
   479→  dataUri: string,
   480→  schemaDescription: string
   481→): Promise<T> {
   482→  const isImage = dataUri.startsWith("data:image/");
   483→  const fileContent = isImage
   484→    ? { type: "image_url" as const, image_url: { url: dataUri } }
   485→    : { type: "file" as const, file: { file_data: dataUri } };
   486→  return safeJsonCompletion([
   487→    {
   488→      role: "system",
   489→      content: [
   490→        "Extract structured data from the provided " + (isImage ? "image" : "document") + ".",
   491→        "Respond ONLY with valid JSON matching the schema.",
   492→        "Use null for any field that cannot be determined.",
   493→        `Schema:\n${schemaDescription}`,
   494→      ].join("\n"),
   495→    },
   496→    {
   497→      role: "user",
   498→      content: [
   499→        { type: "text", text: "Extract the data from this " + (isImage ? "image" : "document") + "." },
   500→        fileContent,
   501→      ],
   502→    },
   503→  ]);
   504→}
   505→
   506→```
