    54→  reise: '#06b6d4',
    55→  marketing: '#f59e0b',
    56→  miete: '#10b981',
    57→  versicherung: '#3b82f6',
    58→  sonstiges: '#94a3b8',
    59→};
    60→
    61→export default function DashboardOverview() {
    62→  const { rechnung, loading, error, fetchAll } = useDashboardData();
    63→
    64→  const [search, setSearch] = useState('');
    65→  const [filterStatus, setFilterStatus] = useState<'alle' | 'offen' | 'bezahlt'>('alle');
    66→  const [filterKategorie, setFilterKategorie] = useState<string>('alle');
    67→  const [dialogOpen, setDialogOpen] = useState(false);
    68→  const [editRecord, setEditRecord] = useState<Rechnung | null>(null);
    69→  const [deleteTarget, setDeleteTarget] = useState<Rechnung | null>(null);
    70→  const [deleting, setDeleting] = useState(false);
    71→
    72→  const totalBetrag = useMemo(() => rechnung.reduce((s, r) => s + (r.fields.betrag ?? 0), 0), [rechnung]);
    73→  const offenCount = useMemo(() => rechnung.filter(r => !r.fields.bezahlt).length, [rechnung]);
    74→  const offenBetrag = useMemo(() => rechnung.filter(r => !r.fields.bezahlt).reduce((s, r) => s + (r.fields.betrag ?? 0), 0), [rechnung]);
    75→  const bezahltCount = useMemo(() => rechnung.filter(r => r.fields.bezahlt).length, [rechnung]);
    76→
    77→  const kategorieChartData = useMemo(() => {
    78→    const map: Record<string, number> = {};
    79→    rechnung.forEach(r => {
    80→      const k = lookupKey(r.fields.kategorie) ?? 'sonstiges';
    81→      map[k] = (map[k] ?? 0) + (r.fields.betrag ?? 0);
    82→    });
    83→    return Object.entries(map)
    84→      .map(([key, value]) => ({ key, label: CATEGORY_LABELS[key] ?? key, value }))
    85→      .sort((a, b) => b.value - a.value);
    86→  }, [rechnung]);
    87→
    88→  const kategorieOptions = useMemo(() => {
    89→    const keys = [...new Set(rechnung.map(r => lookupKey(r.fields.kategorie)).filter(Boolean))] as string[];
    90→    return keys;
    91→  }, [rechnung]);
    92→
    93→  const filtered = useMemo(() => {
    94→    return rechnung.filter(r => {
    95→      if (filterStatus === 'offen' && r.fields.bezahlt) return false;
    96→      if (filterStatus === 'bezahlt' && !r.fields.bezahlt) return false;
    97→      if (filterKategorie !== 'alle') {
    98→        const k = lookupKey(r.fields.kategorie);
    99→        if (k !== filterKategorie) return false;
   100→      }
   101→      if (search.trim()) {
   102→        const q = search.toLowerCase();
   103→        const num = r.fields.rechnungsnummer?.toLowerCase() ?? '';
   104→        const lief = r.fields.lieferant?.toLowerCase() ?? '';
   105→        if (!num.includes(q) && !lief.includes(q)) return false;
   106→      }
   107→      return true;
   108→    }).sort((a, b) => {
   109→      const da = a.fields.rechnungsdatum ?? '';
   110→      const db = b.fields.rechnungsdatum ?? '';
   111→      return db.localeCompare(da);
   112→    });
   113→  }, [rechnung, filterStatus, filterKategorie, search]);
   114→
   115→  const handleCreate = useCallback(async (fields: Rechnung['fields']) => {
   116→    await LivingAppsService.createRechnungEntry(fields);
   117→    fetchAll();
   118→  }, [fetchAll]);
   119→
   120→  const handleEdit = useCallback(async (fields: Rechnung['fields']) => {
   121→    if (!editRecord) return;
   122→    await LivingAppsService.updateRechnungEntry(editRecord.record_id, fields);
   123→    fetchAll();
   124→  }, [editRecord, fetchAll]);
   125→
   126→  const handleToggleBezahlt = useCallback(async (r: Rechnung) => {
   127→    await LivingAppsService.updateRechnungEntry(r.record_id, { bezahlt: !r.fields.bezahlt });
   128→    fetchAll();
   129→  }, [fetchAll]);
   130→
   131→  const handleDelete = useCallback(async () => {
   132→    if (!deleteTarget) return;
   133→    setDeleting(true);
   134→    try {
   135→      await LivingAppsService.deleteRechnungEntry(deleteTarget.record_id);
   136→      fetchAll();
   137→    } finally {
   138→      setDeleting(false);
   139→      setDeleteTarget(null);
   140→    }
   141→  }, [deleteTarget, fetchAll]);
   142→
   143→  if (loading) return <DashboardSkeleton />;
   144→  if (error) return <DashboardError error={error} onRetry={fetchAll} />;
   145→
   146→  return (
   147→    <div className="space-y-6">
   148→      {/* Header */}
   149→      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
   150→        <div>
   151→          <h1 className="text-2xl font-bold text-foreground">Rechnungsübersicht</h1>
   152→          <p className="text-sm text-muted-foreground mt-0.5">{rechnung.length} Rechnung{rechnung.length !== 1 ? 'en' : ''} gesamt</p>
   153→        </div>
   154→        <Button
   155→          onClick={() => { setEditRecord(null); setDialogOpen(true); }}
   156→          className="gap-2 shrink-0"
   157→        >
   158→          <Plus size={16} />
   159→          Neue Rechnung
   160→        </Button>
   161→      </div>
   162→
   163→      {/* KPI Cards */}
   164→      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   165→        <StatCard
   166→          title="Gesamtbetrag"
   167→          value={formatCurrency(totalBetrag).replace('$', '€')}
   168→          description="Alle Rechnungen"
   169→          icon={<Euro size={18} className="text-muted-foreground" />}
   170→        />
   171→        <StatCard
   172→          title="Offen"
   173→          value={String(offenCount)}
   174→          description={`${formatCurrency(offenBetrag).replace('$', '€')} ausstehend`}
   175→          icon={<Clock size={18} className="text-amber-500" />}
   176→        />
   177→        <StatCard
   178→          title="Bezahlt"
   179→          value={String(bezahltCount)}
   180→          description="Abgeschlossen"
   181→          icon={<CheckCircle2 size={18} className="text-emerald-500" />}
   182→        />
   183→        <StatCard
   184→          title="Kategorien"
   185→          value={String(kategorieOptions.length)}
   186→          description="Kostenarten"
   187→          icon={<TrendingUp size={18} className="text-muted-foreground" />}
   188→        />
   189→      </div>
   190→
   191→      {/* Chart + Filters Row */}
   192→      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
   193→        {/* Category Chart */}
   194→        {kategorieChartData.length > 0 && (
   195→          <div className="lg:col-span-2 bg-card border border-border rounded-2xl p-5">
   196→            <h2 className="text-sm font-semibold text-foreground mb-1">Ausgaben nach Kategorie</h2>
   197→            <p className="text-xs text-muted-foreground mb-4">Betrag in EUR</p>
   198→            <ResponsiveContainer width="100%" height={180}>
   199→              <BarChart data={kategorieChartData} barSize={28} margin={{ top: 0, right: 8, left: 0, bottom: 0 }}>
   200→                <XAxis
   201→                  dataKey="label"
   202→                  tick={{ fontSize: 11, fill: 'var(--muted-foreground)' }}
   203→                  tickLine={false}
   204→                  axisLine={false}
   205→                  interval={0}
   206→                  angle={-20}
   207→                  textAnchor="end"
   208→                  height={48}
   209→                />
   210→                <YAxis
   211→                  tick={{ fontSize: 11, fill: 'var(--muted-foreground)' }}
   212→                  tickLine={false}
   213→                  axisLine={false}
   214→                  tickFormatter={(v) => `${v}€`}
   215→                />
   216→                <Tooltip
   217→                  contentStyle={{ backgroundColor: 'var(--background)', border: '1px solid var(--border)', borderRadius: 8, fontSize: 12 }}
   218→                  formatter={(v: number) => [`${v.toFixed(2)} €`, 'Betrag']}
   219→                />
   220→                {kategorieChartData.map((entry) => (
   221→                  <Bar key={entry.key} dataKey="value" radius={[4, 4, 0, 0]}>
   222→                    <Cell fill={CATEGORY_COLORS[entry.key] ?? '#6366f1'} />
   223→                  </Bar>
   224→                ))}
   225→              </BarChart>
   226→            </ResponsiveContainer>
   227→          </div>
   228→        )}
   229→
   230→        {/* Quick Status Filter Panel */}
   231→        <div className="bg-card border border-border rounded-2xl p-5 flex flex-col gap-3">
   232→          <h2 className="text-sm font-semibold text-foreground">Filter</h2>
   233→
   234→          {/* Status Filter */}
   235→          <div className="space-y-1.5">
   236→            <p className="text-xs text-muted-foreground uppercase tracking-wider">Status</p>
   237→            <div className="flex flex-col gap-1">
   238→              {(['alle', 'offen', 'bezahlt'] as const).map(s => (
   239→                <button
   240→                  key={s}
   241→                  onClick={() => setFilterStatus(s)}
   242→                  className={`flex items-center justify-between px-3 py-2 rounded-lg text-sm font-medium transition-colors text-left ${
   243→                    filterStatus === s
   244→                      ? 'bg-primary text-primary-foreground'
   245→                      : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
   246→                  }`}
   247→                >
   248→                  <span className="capitalize">{s === 'alle' ? 'Alle' : s === 'offen' ? 'Offen' : 'Bezahlt'}</span>
   249→                  <span className={`text-xs px-1.5 py-0.5 rounded-full ${filterStatus === s ? 'bg-primary-foreground/20 text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>
   250→                    {s === 'alle' ? rechnung.length : s === 'offen' ? offenCount : bezahltCount}
   251→                  </span>
   252→                </button>
   253→              ))}
   254→            </div>
   255→          </div>
   256→
   257→          {/* Category Filter */}
   258→          {kategorieOptions.length > 0 && (
   259→            <div className="space-y-1.5">
   260→              <p className="text-xs text-muted-foreground uppercase tracking-wider">Kategorie</p>
   261→              <div className="flex flex-col gap-1 max-h-40 overflow-y-auto">
   262→                <button
   263→                  onClick={() => setFilterKategorie('alle')}
   264→                  className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors text-left ${
   265→                    filterKategorie === 'alle'
   266→                      ? 'bg-primary/10 text-primary'
   267→                      : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
   268→                  }`}
   269→                >
   270→                  <Filter size={12} />
   271→                  Alle Kategorien
   272→                </button>
   273→                {kategorieOptions.map(k => (
   274→                  <button
   275→                    key={k}
   276→                    onClick={() => setFilterKategorie(k)}
   277→                    className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm transition-colors text-left ${
   278→                      filterKategorie === k
   279→                        ? 'bg-primary/10 text-primary font-medium'
   280→                        : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
   281→                    }`}
   282→                  >
   283→                    <span
   284→                      className="w-2 h-2 rounded-full shrink-0"
   285→                      style={{ backgroundColor: CATEGORY_COLORS[k] ?? '#94a3b8' }}
   286→                    />
   287→                    {CATEGORY_LABELS[k] ?? k}
   288→                  </button>
   289→                ))}
   290→              </div>
   291→            </div>
   292→          )}
   293→        </div>
   294→      </div>
   295→
   296→      {/* Invoice List */}
   297→      <div className="bg-card border border-border rounded-2xl overflow-hidden">
   298→        {/* Search Bar */}
   299→        <div className="flex items-center gap-3 px-5 py-4 border-b border-border">
   300→          <div className="relative flex-1 max-w-sm">
   301→            <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
   302→            <Input
   303→              placeholder="Suche nach Nummer, Lieferant..."
   304→              className="pl-9 h-9 text-sm"
   305→              value={search}
   306→              onChange={e => setSearch(e.target.value)}
   307→            />
   308→          </div>
   309→          <span className="text-sm text-muted-foreground shrink-0">
   310→            {filtered.length} Ergebnis{filtered.length !== 1 ? 'se' : ''}
   311→          </span>
   312→        </div>
   313→
   314→        {/* Invoice Rows */}
   315→        {filtered.length === 0 ? (
   316→          <div className="flex flex-col items-center justify-center py-16 gap-3">
   317→            <div className="w-12 h-12 rounded-2xl bg-muted flex items-center justify-center">
   318→              <Receipt size={22} className="text-muted-foreground" />
   319→            </div>
   320→            <div className="text-center">
   321→              <p className="font-semibold text-foreground text-sm">Keine Rechnungen</p>
   322→              <p className="text-xs text-muted-foreground mt-1">
   323→                {search || filterStatus !== 'alle' || filterKategorie !== 'alle'
   324→                  ? 'Keine Treffer für aktuelle Filter'
   325→                  : 'Erstellen Sie Ihre erste Rechnung'}
   326→              </p>
   327→            </div>
   328→            {!search && filterStatus === 'alle' && filterKategorie === 'alle' && (
   329→              <Button size="sm" variant="outline" onClick={() => { setEditRecord(null); setDialogOpen(true); }} className="gap-2">
   330→                <Plus size={14} />
   331→                Rechnung erstellen
   332→              </Button>
   333→            )}
   334→          </div>
   335→        ) : (
   336→          <div className="divide-y divide-border">
   337→            {filtered.map(r => {
   338→              const katKey = lookupKey(r.fields.kategorie);
   339→              const katLabel = katKey ? (CATEGORY_LABELS[katKey] ?? displayLookup(r.fields.kategorie)) : null;
   340→              const katColor = katKey ? (CATEGORY_COLORS[katKey] ?? '#94a3b8') : '#94a3b8';
   341→              return (
   342→                <div
   343→                  key={r.record_id}
   344→                  className="flex items-center gap-4 px-5 py-4 hover:bg-accent/30 transition-colors group"
   345→                >
   346→                  {/* Status dot */}
   347→                  <div className="shrink-0">
   348→                    <button
   349→                      onClick={() => handleToggleBezahlt(r)}
   350→                      title={r.fields.bezahlt ? 'Als offen markieren' : 'Als bezahlt markieren'}
   351→                      className="transition-transform hover:scale-110"
   352→                    >
   353→                      {r.fields.bezahlt
   354→                        ? <CheckCircle2 size={22} className="text-emerald-500" />
   355→                        : <Clock size={22} className="text-amber-500" />
   356→                      }
   357→                    </button>
   358→                  </div>
   359→
   360→                  {/* Main info */}
   361→                  <div className="flex-1 min-w-0">
   362→                    <div className="flex items-center gap-2 flex-wrap">
   363→                      <span className="font-semibold text-foreground text-sm truncate">
   364→                        {r.fields.rechnungsnummer ?? '—'}
   365→                      </span>
   366→                      {katLabel && (
   367→                        <Badge
   368→                          variant="secondary"
   369→                          className="text-xs px-2 py-0 font-normal gap-1"
   370→                          style={{ borderLeft: `3px solid ${katColor}` }}
   371→                        >
   372→                          <Tag size={10} />
   373→                          {katLabel}
   374→                        </Badge>
   375→                      )}
   376→                      {!r.fields.bezahlt && (
   377→                        <Badge variant="outline" className="text-xs px-2 py-0 text-amber-600 border-amber-300 bg-amber-50">
   378→                          Offen
   379→                        </Badge>
   380→                      )}
   381→                    </div>
   382→                    <div className="flex items-center gap-3 mt-1 flex-wrap">
   383→                      {r.fields.lieferant && (
   384→                        <span className="flex items-center gap-1 text-xs text-muted-foreground">
   385→                          <Building2 size={11} />
   386→                          {r.fields.lieferant}
   387→                        </span>
   388→                      )}
   389→                      {r.fields.rechnungsdatum && (
   390→                        <span className="flex items-center gap-1 text-xs text-muted-foreground">
   391→                          <CalendarDays size={11} />
   392→                          {formatDate(r.fields.rechnungsdatum)}
   393→                        </span>
   394→                      )}
   395→                      {r.fields.rechnungsdatei && (
   396→                        <a
   397→                          href={r.fields.rechnungsdatei}
   398→                          target="_blank"
   399→                          rel="noopener noreferrer"
   400→                          className="flex items-center gap-1 text-xs text-primary hover:underline"
   401→                          onClick={e => e.stopPropagation()}
   402→                        >
   403→                          <FileText size={11} />
   404→                          Datei
   405→                        </a>
   406→                      )}
   407→                    </div>
   408→                    {r.fields.notizen && (
   409→                      <p className="text-xs text-muted-foreground mt-1 truncate max-w-md">{r.fields.notizen}</p>
   410→                    )}
   411→                  </div>
   412→
   413→                  {/* Amount */}
   414→                  <div className="shrink-0 text-right">
   415→                    <p className={`font-bold text-base tabular-nums ${r.fields.bezahlt ? 'text-muted-foreground' : 'text-foreground'}`}>
   416→                      {r.fields.betrag != null ? `${r.fields.betrag.toFixed(2)} €` : '—'}
   417→                    </p>
   418→                  </div>
   419→
   420→                  {/* Actions */}
   421→                  <div className="shrink-0 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
   422→                    <Button
   423→                      variant="ghost"
   424→                      size="icon"
   425→                      className="h-8 w-8"
   426→                      onClick={() => { setEditRecord(r); setDialogOpen(true); }}
   427→                    >
   428→                      <Pencil size={14} />
   429→                    </Button>
   430→                    <Button
   431→                      variant="ghost"
   432→                      size="icon"
   433→                      className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
   434→                      onClick={() => setDeleteTarget(r)}
   435→                    >
   436→                      <Trash2 size={14} />
   437→                    </Button>
   438→                  </div>
   439→                </div>
   440→              );
   441→            })}
   442→          </div>
   443→        )}
   444→      </div>
   445→
   446→      {/* Dialogs */}
   447→      <RechnungDialog
   448→        open={dialogOpen}
   449→        onClose={() => { setDialogOpen(false); setEditRecord(null); }}
   450→        onSubmit={editRecord ? handleEdit : handleCreate}
   451→        defaultValues={editRecord?.fields}
   452→        enablePhotoScan={AI_PHOTO_SCAN['Rechnung']}
   453→      />
   454→
   455→      <ConfirmDialog
   456→        open={!!deleteTarget}
   457→        title="Rechnung löschen"
   458→        description={`Soll die Rechnung „${deleteTarget?.fields.rechnungsnummer ?? deleteTarget?.record_id}" wirklich gelöscht werden?`}
   459→        onConfirm={handleDelete}
   460→        onClose={() => setDeleteTarget(null)}
   461→      />
   462→    </div>
   463→  );
   464→}
   465→
   466→function DashboardSkeleton() {
   467→  return (
   468→    <div className="space-y-6">
   469→      <div className="flex items-center justify-between">
   470→        <Skeleton className="h-8 w-48" />
   471→        <Skeleton className="h-9 w-36" />
   472→      </div>
   473→      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   474→        {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-24 rounded-2xl" />)}
   475→      </div>
   476→      <Skeleton className="h-64 rounded-2xl" />
   477→      <Skeleton className="h-96 rounded-2xl" />
   478→    </div>
   479→  );
   480→}
   481→
   482→function DashboardError({ error, onRetry }: { error: Error; onRetry: () => void }) {
   483→  return (
   484→    <div className="flex flex-col items-center justify-center py-24 gap-4">
   485→      <div className="w-12 h-12 rounded-2xl bg-destructive/10 flex items-center justify-center">
   486→        <AlertCircle size={22} className="text-destructive" />
   487→      </div>
   488→      <div className="text-center">
   489→        <h3 className="font-semibold text-foreground mb-1">Fehler beim Laden</h3>
   490→        <p className="text-sm text-muted-foreground max-w-xs">{error.message}</p>
   491→      </div>
   492→      <Button variant="outline" size="sm" onClick={onRetry}>Erneut versuchen</Button>
   493→    </div>
   494→  );
   495→}
   496→

toolUseResult.content:
import { useState, useMemo, useCallback } from 'react';
import { useDashboardData } from '@/hooks/useDashboardData';
import type { Rechnung } from '@/types/app';
import { LivingAppsService } from '@/services/livingAppsService';
import { formatDate, formatCurrency, displayLookup, lookupKey } from '@/lib/formatters';
import { Skeleton } from '@/components/ui/skeleton';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { StatCard } from '@/components/StatCard';
import { ConfirmDialog } from '@/components/ConfirmDialog';
import { RechnungDialog } from '@/components/dialogs/RechnungDialog';
import { AI_PHOTO_SCAN } from '@/config/ai-features';
import {
  AlertCircle,
  Plus,
  Search,
  Receipt,
  CheckCircle2,
  Clock,
  TrendingUp,
  Euro,
  Pencil,
  Trash2,
  FileText,
  Tag,
  Building2,
  CalendarDays,
  Filter,
} from 'lucide-react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  Cell,
} from 'recharts';

const CATEGORY_LABELS: Record<string, string> = {
  buero: 'Büromaterial',
  it_software: 'IT & Software',
  reise: 'Reisekosten',
  marketing: 'Marketing',
  miete: 'Miete & Nebenkosten',
  versicherung: 'Versicherungen',
  sonstiges: 'Sonstiges',
};

const CATEGORY_COLORS: Record<string, string> = {
  buero: '#6366f1',
  it_software: '#8b5cf6',
  reise: '#06b6d4',
  marketing: '#f59e0b',
  miete: '#10b981',
  versicherung: '#3b82f6',
  sonstiges: '#94a3b8',
};

export default function DashboardOverview() {
  const { rechnung, loading, error, fetchAll } = useDashboardData();

  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<'alle' | 'offen' | 'bezahlt'>('alle');
  const [filterKategorie, setFilterKategorie] = useState<string>('alle');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editRecord, setEditRecord] = useState<Rechnung | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<Rechnung | null>(null);
  const [deleting, setDeleting] = useState(false);

  const totalBetrag = useMemo(() => rechnung.reduce((s, r) => s + (r.fields.betrag ?? 0), 0), [rechnung]);
  const offenCount = useMemo(() => rechnung.filter(r => !r.fields.bezahlt).length, [rechnung]);
  const offenBetrag = useMemo(() => rechnung.filter(r => !r.fields.bezahlt).reduce((s, r) => s + (r.fields.betrag ?? 0), 0), [rechnung]);
  const bezahltCount = useMemo(() => rechnung.filter(r => r.fields.bezahlt).length, [rechnung]);

  const kategorieChartData = useMemo(() => {
    const map: Record<string, number> = {};
    rechnung.forEach(r => {
      const k = lookupKey(r.fields.kategorie) ?? 'sonstiges';
      map[k] = (map[k] ?? 0) + (r.fields.betrag ?? 0);
    });
    return Object.entries(map)
      .map(([key, value]) => ({ key, label: CATEGORY_LABELS[key] ?? key, value }))
      .sort((a, b) => b.value - a.value);
  }, [rechnung]);

  const kategorieOptions = useMemo(() => {
    const keys = [...new Set(rechnung.map(r => lookupKey(r.fields.kategorie)).filter(Boolean))] as string[];
    return keys;
  }, [rechnung]);

  const filtered = useMemo(() => {
    return rechnung.filter(r => {
      if (filterStatus === 'offen' && r.fields.bezahlt) return false;
      if (filterStatus === 'bezahlt' && !r.fields.bezahlt) return false;
      if (filterKategorie !== 'alle') {
        const k = lookupKey(r.fields.kategorie);
        if (k !== filterKategorie) return false;
      }
      if (search.trim()) {
        const q = search.toLowerCase();
        const num = r.fields.rechnungsnummer?.toLowerCase() ?? '';
        const lief = r.fields.lieferant?.toLowerCase() ?? '';
        if (!num.includes(q) && !lief.includes(q)) return false;
      }
      return true;
    }).sort((a, b) => {
      const da = a.fields.rechnungsdatum ?? '';
      const db = b.fields.rechnungsdatum ?? '';
      return db.localeCompare(da);
    });
  }, [rechnung, filterStatus, filterKategorie, search]);

  const handleCreate = useCallback(async (fields: Rechnung['fields']) => {
    await LivingAppsService.createRechnungEntry(fields);
    fetchAll();
  }, [fetchAll]);

  const handleEdit = useCallback(async (fields: Rechnung['fields']) => {
    if (!editRecord) return;
    await LivingAppsService.updateRechnungEntry(editRecord.record_id, fields);
    fetchAll();
  }, [editRecord, fetchAll]);

  const handleToggleBezahlt = useCallback(async (r: Rechnung) => {
    await LivingAppsService.updateRechnungEntry(r.record_id, { bezahlt: !r.fields.bezahlt });
    fetchAll();
  }, [fetchAll]);

  const handleDelete = useCallback(async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await LivingAppsService.deleteRechnungEntry(deleteTarget.record_id);
      fetchAll();
    } finally {
      setDeleting(false);
      setDeleteTarget(null);
    }
  }, [deleteTarget, fetchAll]);

  if (loading) return <DashboardSkeleton />;
  if (error) return <DashboardError error={error} onRetry={fetchAll} />;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Rechnungsübersicht</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{rechnung.length} Rechnung{rechnung.length !== 1 ? 'en' : ''} gesamt</p>
        </div>
        <Button
          onClick={() => { setEditRecord(null); setDialogOpen(true); }}
          className="gap-2 shrink-0"
        >
          <Plus size={16} />
          Neue Rechnung
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <StatCard
          title="Gesamtbetrag"
          value={formatCurrency(totalBetrag).replace('$', '€')}
          description="Alle Rechnungen"
          icon={<Euro size={18} className="text-muted-foreground" />}
        />
        <StatCard
          title="Offen"
          value={String(offenCount)}
          description={`${formatCurrency(offenBetrag).replace('$', '€')} ausstehend`}
          icon={<Clock size={18} className="text-amber-500" />}
        />
        <StatCard
          title="Bezahlt"
          value={String(bezahltCount)}
          description="Abgeschlossen"
          icon={<CheckCircle2 size={18} className="text-emerald-500" />}
        />
        <StatCard
          title="Kategorien"
          value={String(kategorieOptions.length)}
          description="Kostenarten"
          icon={<TrendingUp size={18} className="text-muted-foreground" />}
        />
      </div>

      {/* Chart + Filters Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Category Chart */}
        {kategorieChartData.length > 0 && (
          <div className="lg:col-span-2 bg-card border border-border rounded-2xl p-5">
            <h2 className="text-sm font-semibold text-foreground mb-1">Ausgaben nach Kategorie</h2>
            <p className="text-xs text-muted-foreground mb-4">Betrag in EUR</p>
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={kategorieChartData} barSize={28} margin={{ top: 0, right: 8, left: 0, bottom: 0 }}>
                <XAxis
                  dataKey="label"
                  tick={{ fontSize: 11, fill: 'var(--muted-foreground)' }}
                  tickLine={false}
                  axisLine={false}
                  interval={0}
                  angle={-20}
                  textAnchor="end"
                  height={48}
                />
                <YAxis
                  tick={{ fontSize: 11, fill: 'var(--muted-foreground)' }}
                  tickLine={false}
                  axisLine={false}
                  tickFormatter={(v) => `${v}€`}
                />
                <Tooltip
                  contentStyle={{ backgroundColor: 'var(--background)', border: '1px solid var(--border)', borderRadius: 8, fontSize: 12 }}
                  formatter={(v: number) => [`${v.toFixed(2)} €`, 'Betrag']}
                />
                {kategorieChartData.map((entry) => (
                  <Bar key={entry.key} dataKey="value" radius={[4, 4, 0, 0]}>
                    <Cell fill={CATEGORY_COLORS[entry.key] ?? '#6366f1'} />
                  </Bar>
                ))}
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}

        {/* Quick Status Filter Panel */}
        <div className="bg-card border border-border rounded-2xl p-5 flex flex-col gap-3">
          <h2 className="text-sm font-semibold text-foreground">Filter</h2>

          {/* Status Filter */}
          <div className="space-y-1.5">
            <p className="text-xs text-muted-foreground uppercase tracking-wider">Status</p>
            <div className="flex flex-col gap-1">
              {(['alle', 'offen', 'bezahlt'] as const).map(s => (
                <button
                  key={s}
                  onClick={() => setFilterStatus(s)}
                  className={`flex items-center justify-between px-3 py-2 rounded-lg text-sm font-medium transition-colors text-left ${
                    filterStatus === s
                      ? 'bg-primary text-primary-foreground'
                      : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
                  }`}
                >
                  <span className="capitalize">{s === 'alle' ? 'Alle' : s === 'offen' ? 'Offen' : 'Bezahlt'}</span>
                  <span className={`text-xs px-1.5 py-0.5 rounded-full ${filterStatus === s ? 'bg-primary-foreground/20 text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>
                    {s === 'alle' ? rechnung.length : s === 'offen' ? offenCount : bezahltCount}
                  </span>
                </button>
              ))}
            </div>
          </div>

          {/* Category Filter */}
          {kategorieOptions.length > 0 && (
            <div className="space-y-1.5">
              <p className="text-xs text-muted-foreground uppercase tracking-wider">Kategorie</p>
              <div className="flex flex-col gap-1 max-h-40 overflow-y-auto">
                <button
                  onClick={() => setFilterKategorie('alle')}
                  className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors text-left ${
                    filterKategorie === 'alle'
                      ? 'bg-primary/10 text-primary'
                      : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
                  }`}
                >
                  <Filter size={12} />
                  Alle Kategorien
                </button>
                {kategorieOptions.map(k => (
                  <button
                    key={k}
                    onClick={() => setFilterKategorie(k)}
                    className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm transition-colors text-left ${
                      filterKategorie === k
                        ? 'bg-primary/10 text-primary font-medium'
                        : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground'
                    }`}
                  >
                    <span
                      className="w-2 h-2 rounded-full shrink-0"
                      style={{ backgroundColor: CATEGORY_COLORS[k] ?? '#94a3b8' }}
                    />
                    {CATEGORY_LABELS[k] ?? k}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Invoice List */}
      <div className="bg-card border border-border rounded-2xl overflow-hidden">
        {/* Search Bar */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-border">
          <div className="relative flex-1 max-w-sm">
            <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Suche nach Nummer, Lieferant..."
              className="pl-9 h-9 text-sm"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <span className="text-sm text-muted-foreground shrink-0">
            {filtered.length} Ergebnis{filtered.length !== 1 ? 'se' : ''}
          </span>
        </div>

        {/* Invoice Rows */}
        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-3">
            <div className="w-12 h-12 rounded-2xl bg-muted flex items-center justify-center">
              <Receipt size={22} className="text-muted-foreground" />
            </div>
            <div className="text-center">
              <p className="font-semibold text-foreground text-sm">Keine Rechnungen</p>
              <p className="text-xs text-muted-foreground mt-1">
                {search || filterStatus !== 'alle' || filterKategorie !== 'alle'
                  ? 'Keine Treffer für aktuelle Filter'
                  : 'Erstellen Sie Ihre erste Rechnung'}
              </p>
            </div>
            {!search && filterStatus === 'alle' && filterKategorie === 'alle' && (
              <Button size="sm" variant="outline" onClick={() => { setEditRecord(null); setDialogOpen(true); }} className="gap-2">
                <Plus size={14} />
                Rechnung erstellen
              </Button>
            )}
          </div>
        ) : (
          <div className="divide-y divide-border">
            {filtered.map(r => {
              const katKey = lookupKey(r.fields.kategorie);
              const katLabel = katKey ? (CATEGORY_LABELS[katKey] ?? displayLookup(r.fields.kategorie)) : null;
              const katColor = katKey ? (CATEGORY_COLORS[katKey] ?? '#94a3b8') : '#94a3b8';
              return (
                <div
                  key={r.record_id}
                  className="flex items-center gap-4 px-5 py-4 hover:bg-accent/30 transition-colors group"
                >
                  {/* Status dot */}
                  <div className="shrink-0">
                    <button
                      onClick={() => handleToggleBezahlt(r)}
                      title={r.fields.bezahlt ? 'Als offen markieren' : 'Als bezahlt markieren'}
                      className="transition-transform hover:scale-110"
                    >
                      {r.fields.bezahlt
                        ? <CheckCircle2 size={22} className="text-emerald-500" />
                        : <Clock size={22} className="text-amber-500" />
                      }
                    </button>
                  </div>

                  {/* Main info */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-semibold text-foreground text-sm truncate">
                        {r.fields.rechnungsnummer ?? '—'}
                      </span>
                      {katLabel && (
                        <Badge
                          variant="secondary"
                          className="text-xs px-2 py-0 font-normal gap-1"
                          style={{ borderLeft: `3px solid ${katColor}` }}
                        >
                          <Tag size={10} />
                          {katLabel}
                        </Badge>
                      )}
                      {!r.fields.bezahlt && (
                        <Badge variant="outline" className="text-xs px-2 py-0 text-amber-600 border-amber-300 bg-amber-50">
                          Offen
                        </Badge>
                      )}
                    </div>
                    <div className="flex items-center gap-3 mt-1 flex-wrap">
                      {r.fields.lieferant && (
                        <span className="flex items-center gap-1 text-xs text-muted-foreground">
                          <Building2 size={11} />
                          {r.fields.lieferant}
                        </span>
                      )}
                      {r.fields.rechnungsdatum && (
                        <span className="flex items-center gap-1 text-xs text-muted-foreground">
                          <CalendarDays size={11} />
                          {formatDate(r.fields.rechnungsdatum)}
                        </span>
                      )}
                      {r.fields.rechnungsdatei && (
                        <a
                          href={r.fields.rechnungsdatei}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center gap-1 text-xs text-primary hover:underline"
                          onClick={e => e.stopPropagation()}
                        >
                          <FileText size={11} />
                          Datei
                        </a>
                      )}
                    </div>
                    {r.fields.notizen && (
                      <p className="text-xs text-muted-foreground mt-1 truncate max-w-md">{r.fields.notizen}</p>
                    )}
                  </div>

                  {/* Amount */}
                  <div className="shrink-0 text-right">
                    <p className={`font-bold text-base tabular-nums ${r.fields.bezahlt ? 'text-muted-foreground' : 'text-foreground'}`}>
                      {r.fields.betrag != null ? `${r.fields.betrag.toFixed(2)} €` : '—'}
                    </p>
                  </div>

                  {/* Actions */}
                  <div className="shrink-0 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                      onClick={() => { setEditRecord(r); setDialogOpen(true); }}
                    >
                      <Pencil size={14} />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                      onClick={() => setDeleteTarget(r)}
                    >
                      <Trash2 size={14} />
                    </Button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Dialogs */}
      <RechnungDialog
        open={dialogOpen}
        onClose={() => { setDialogOpen(false); setEditRecord(null); }}
        onSubmit={editRecord ? handleEdit : handleCreate}
        defaultValues={editRecord?.fields}
        enablePhotoScan={AI_PHOTO_SCAN['Rechnung']}
      />

      <ConfirmDialog
        open={!!deleteTarget}
        title="Rechnung löschen"
        description={`Soll die Rechnung „${deleteTarget?.fields.rechnungsnummer ?? deleteTarget?.record_id}" wirklich gelöscht werden?`}
        onConfirm={handleDelete}
        onClose={() => setDeleteTarget(null)}
      />
    </div>
  );
}

function DashboardSkeleton() {
  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-9 w-36" />
      </div>
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-24 rounded-2xl" />)}
      </div>
      <Skeleton className="h-64 rounded-2xl" />
      <Skeleton className="h-96 rounded-2xl" />
    </div>
  );
}

function DashboardError({ error, onRetry }: { error: Error; onRetry: () => void }) {
  return (
    <div className="flex flex-col items-center justify-center py-24 gap-4">
      <div className="w-12 h-12 rounded-2xl bg-destructive/10 flex items-center justify-center">
        <AlertCircle size={22} className="text-destructive" />
      </div>
      <div className="text-center">
        <h3 className="font-semibold text-foreground mb-1">Fehler beim Laden</h3>
        <p className="text-sm text-muted-foreground max-w-xs">{error.message}</p>
      </div>
      <Button variant="outline" size="sm" onClick={onRetry}>Erneut versuchen</Button>
    </div>
  );
}

